import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
K=['RSPP-A','RSPP-AGG']
EA(K,'ZR01','Quando risponde l’RSPP',[LB("Laboratorio · L’RSPP e l’infortunio","Sei chiamato ad analizzare la posizione dell’RSPP esterno dopo un infortunio in un’officina.",[
  ["Evento","un operaio si amputa una falange su un tornio parallelo privo di schermo paratrucioli interbloccato"],["DVR","redatto dall’RSPP due anni prima; il tornio è valutato «rischio basso» senza motivazione"],["Sopralluoghi","l’RSPP ha svolto due sopralluoghi annuali; nei verbali il tornio non è citato"],["Datore di lavoro","dichiara che avrebbe installato lo schermo se gli fosse stato segnalato"]],[
  ("L’RSPP ha sanzioni contravvenzionali proprie? Di che cosa può rispondere?",6,"No: il D.lgs. 81/2008 non prevede contravvenzioni proprie per l’RSPP. Può rispondere di lesioni colpose in concorso con il datore di lavoro, se un errore di valutazione o un’omessa segnalazione ha contribuito all’evento.",["Ho escluso le contravvenzioni proprie","Ho indicato il concorso nelle lesioni colpose"]),
  ("Quali elementi del caso pesano contro l’RSPP?",8,"La valutazione «rischio basso» senza motivazione per una macchina con organi in movimento non protetti; l’assenza del tornio nei verbali dei sopralluoghi; la mancanza di segnalazioni scritte. La dichiarazione del datore di lavoro sostiene il nesso causale: con la segnalazione la misura sarebbe stata adottata.",["Ho individuato l’errore di valutazione","Ho individuato l’omessa segnalazione","Ho collegato il nesso causale"],None,120),
  ("Quali elementi potrebbero invece tutelarlo?",6,"Una segnalazione scritta del rischio precedente all’evento; proposte di misure documentate e rimaste inattuate per decisione del datore di lavoro; verbali di sopralluogo dettagliati. In assenza di questi documenti la difesa è debole.",["Ho indicato le segnalazioni scritte","Ho indicato le proposte documentate"]),
  ("Scrivi tre regole di lavoro che un RSPP dovrebbe seguire per tutelarsi.",8,"Motivare ogni valutazione con criteri espliciti e dati; segnalare per iscritto, con data, ogni rischio rilevato e la misura proposta, chiedendo un riscontro; registrare i sopralluoghi con le macchine e le aree visitate e seguire nel tempo lo stato delle proposte.",["Ho previsto valutazioni motivate","Ho previsto segnalazioni scritte con riscontro","Ho previsto il monitoraggio delle proposte"],None,120)],
 "Nel laboratorio analizzi la posizione di un RSPP dopo un infortunio su un tornio. Stabilisci di che cosa può rispondere, quali elementi pesano contro di lui e quali lo tutelerebbero, poi scrivi tre regole di lavoro. Confronta ogni risposta con la soluzione di riferimento.","Artt. 31-33 D.lgs. 81/2008 · Cass. pen., Sezioni Unite, n. 38343/2014")])
EA(K,'ZR02','Analizzare un infortunio: il modello «Infor.MO»',[LB("Laboratorio · Ricostruire un infortunio con Infor.MO","Analizzi con il modello Infor.MO un infortunio avvenuto in un’impresa di logistica.",[
  ["Evento","durante lo scarico di un camion un carrellista retrocede e investe un magazziniere che attraversava la baia di carico"],["Contesto","turno serale, baia poco illuminata, avvisatore acustico di retromarcia guasto da una settimana"],["Organizzazione","nessun percorso pedonale segnato; il magazziniere doveva ritirare una bolla nell’ufficio oltre la baia"],["Conseguenze","frattura della gamba, 90 giorni di prognosi"]],[
  ("Descrivi la dinamica: incidente e modalità di accadimento.",6,"Incidente: il carrello in retromarcia raggiunge la zona in cui transita il pedone. Modalità di accadimento della lesione: urto e schiacciamento della gamba del magazziniere da parte del carrello.",["Ho distinto incidente e modalità","Ho descritto i fatti senza giudizi"]),
  ("Individua i fattori di rischio per categoria.",8,"Attività dell’infortunato: attraversamento della baia per ritirare la bolla. Attività di terzi: retromarcia del carrellista senza visibilità adeguata. Macchina: avvisatore di retromarcia guasto. Ambiente: illuminazione insufficiente e assenza di percorsi pedonali. Organizzazione: ufficio bolle raggiungibile solo attraversando la baia.",["Ho classificato attività, macchina e ambiente","Ho incluso l’organizzazione","Ho individuato più fattori concorrenti"],None,120),
  ("Distingui determinanti e modulatori.",6,"Determinanti: retromarcia senza visibilità e avvisatore guasto, presenza del pedone nella baia. Modulatori: la velocità del carrello e il punto di impatto, che hanno influito sulla gravità della lesione.",["Ho individuato i determinanti","Ho individuato i modulatori"]),
  ("Proponi le misure correttive in ordine di efficacia.",8,"Separare fisicamente pedoni e carrelli con percorsi protetti e spostare l’ufficio bolle o creare un passaggio esterno alla baia; riparare l’avvisatore e prevedere sensori o luci di zona; migliorare l’illuminazione; procedura di verifica dei carrelli a inizio turno; formazione e vigilanza del preposto.",["Ho dato priorità alle misure organizzative e tecniche","Ho previsto la manutenzione","Ho previsto procedure e vigilanza"],None,120)],
 "Nel laboratorio analizzi un investimento in una baia di carico con il modello Infor.MO: descrivi la dinamica, classifica i fattori di rischio, distingui determinanti e modulatori e proponi le misure correttive. Confronta ogni risposta con la soluzione di riferimento.","Modello Infor.MO · INAIL")])
EA(K,'ZR03','Il modello organizzativo dell’art. 30',[LB("Laboratorio · Il modello organizzativo per una PMI","Imposti il modello di organizzazione e gestione dell’art. 30 per una PMI metalmeccanica di 45 lavoratori.",[
  ["Situazione","DVR aggiornato, nessun sistema di gestione certificato"],["Obiettivo","efficacia esimente ai sensi del D.lgs. 231/2001"],["Risorse","RSPP esterno, un responsabile qualità interno"]],[
  ("Quali obblighi giuridici deve presidiare il modello?",7,"Standard tecnico-strutturali di attrezzature, impianti, luoghi e agenti; valutazione dei rischi e misure; emergenze, primo soccorso, appalti, riunioni periodiche, consultazione; sorveglianza sanitaria; informazione e formazione; vigilanza sul rispetto delle procedure; documentazione e certificazioni obbligatorie; verifiche periodiche.",["Ho elencato gli ambiti dell’art. 30, comma 1","Ho incluso la vigilanza"],None,100),
  ("Quali elementi organizzativi aggiungi?",7,"Sistemi di registrazione delle attività; articolazione di funzioni con competenze e poteri; sistema disciplinare per il mancato rispetto delle misure; sistema di controllo sull’attuazione e sul mantenimento del modello; riesame e modifica in caso di violazioni o cambiamenti.",["Ho previsto registrazioni e funzioni","Ho previsto il sistema disciplinare","Ho previsto controllo e riesame"]),
  ("Che cosa prevede la legge per le PMI e per i modelli conformi alle norme?",6,"In sede di prima applicazione i modelli conformi alla UNI EN ISO 45001 si presumono conformi per le parti corrispondenti; per le piccole e medie imprese sono previste procedure semplificate. Il D.L. 159/2025 ha aggiornato il riferimento alla UNI EN ISO 45001.",["Ho citato la presunzione di conformità","Ho citato le procedure semplificate per le PMI"]),
  ("Proponi un piano di attuazione in sei mesi.",7,"Mese 1: analisi delle attività sensibili e dei controlli esistenti. Mesi 2-3: procedure, deleghe, registrazioni e sistema disciplinare. Mese 4: formazione e comunicazione. Mese 5: organismo di vigilanza e flussi informativi. Mese 6: primo audit interno e riesame della direzione.",["Ho previsto l’analisi iniziale","Ho previsto procedure, formazione e organismo di vigilanza","Ho previsto audit e riesame"],None,120)],
 "Nel laboratorio imposti il modello organizzativo dell’articolo trenta per una PMI metalmeccanica: obblighi da presidiare, elementi organizzativi, semplificazioni per le PMI e un piano di attuazione. Confronta ogni risposta con la soluzione di riferimento.","Art. 30 D.lgs. 81/2008 · D.lgs. 231/2001")])
EA(K,'ZR04','Infortunio e responsabilità civile: esonero, regresso e danno differenziale',[ES("Esempio guidato · Il danno differenziale","Che cosa resta a carico del datore di lavoro responsabile.",[
 ["L’evento","Un infortunio con postumi permanenti, di cui il datore di lavoro è riconosciuto responsabile penalmente.","Responsabilità accertata"],
 ["Il danno civilistico","Il giudice liquida il danno complessivo secondo i criteri civilistici: ad esempio 120.000 €.","120.000 €"],
 ["L’indennizzo INAIL","L’INAIL ha indennizzato il danno biologico e patrimoniale nei limiti della sua tutela: ad esempio 70.000 €.","70.000 €"],
 ["Il differenziale","La differenza resta a carico del responsabile: 120.000 − 70.000 = 50.000 €.","50.000 €"],
 ["Il regresso","L’INAIL può agire in regresso per recuperare quanto ha erogato.","Fino a 70.000 € di regresso"]],
 "Vediamo il danno differenziale con importi illustrativi. Il giudice liquida un danno complessivo di centoventimila euro; l’INAIL ha già indennizzato settantamila euro. La differenza, cinquantamila euro, resta a carico del datore di lavoro responsabile, e l’INAIL può agire in regresso per recuperare quanto ha pagato. L’esonero dalla responsabilità civile non opera quando c’è responsabilità penale.","Artt. 10 e 11 D.P.R. 1124/1965")])
EA(K,'ZR05','Il preposto di fatto e il principio di effettività',[LB("Laboratorio · Il preposto di fatto","Analizzi l’organizzazione di un cantiere di manutenzione del verde di un’impresa con 20 operai.",[
  ["Squadre","3 squadre di 4-5 operai"],["Organizzazione","in ogni squadra l’operaio più anziano distribuisce i compiti, decide l’uso delle motoseghe e dà istruzioni ai colleghi"],["Documenti","nessuna lettera di individuazione dei preposti"],["Evento","un operaio usa la motosega senza pantaloni antitaglio, sotto gli occhi del caposquadra"]],[
  ("Gli operai più anziani sono preposti? Motiva.",6,"Sì: per il principio di effettività conta l’esercizio concreto dei poteri. Sovrintendono all’attività, impartiscono istruzioni e controllano l’esecuzione: sono preposti di fatto, con i relativi obblighi.",["Ho applicato il principio di effettività","Ho collegato i compiti alla definizione"]),
  ("Che cosa avrebbe dovuto fare il caposquadra?",5,"Intervenire subito per far cessare il comportamento e far indossare i DPI; se l’inosservanza persiste, interrompere l’attività del lavoratore e informare i superiori.",["Ho indicato intervento e interruzione","Ho indicato l’informazione ai superiori"]),
  ("Quali obblighi ha mancato l’impresa?",7,"Individuare formalmente i preposti, come richiede l’art. 18, comma 1, lettera b-bis; assicurare loro la formazione specifica in presenza e l’aggiornamento biennale; vigilare sul loro operato.",["Ho citato l’individuazione obbligatoria","Ho citato la formazione del preposto"])],
 "Nel laboratorio analizzi l’organizzazione di squadre di manutenzione del verde in cui i capisquadra non sono stati nominati. Stabilisci se sono preposti, che cosa avrebbero dovuto fare e quali obblighi ha mancato l’impresa, poi confronta ogni risposta con la soluzione di riferimento.","Artt. 2, 18, 19 e 299 D.lgs. 81/2008")])
EA(K,'ZR06','Il servizio di prevenzione e protezione',[LB("Laboratorio · Il programma annuale del servizio di prevenzione","Prepari il programma di lavoro annuale del servizio di prevenzione e protezione di un’impresa alimentare con 110 lavoratori.",[
  ["Stato","DVR aggiornato due anni fa; due nuove linee di confezionamento; 6 infortuni e 18 quasi incidenti nell’anno"],["Rischi principali","macchine, movimentazione dei carichi, rumore, celle frigorifere, prodotti per la sanificazione"],["Risorse","RSPP interno e un ASPP part-time"]],[
  ("Elenca i compiti dell’art. 33 che il programma deve coprire.",6,"Individuazione e valutazione dei rischi; elaborazione delle misure preventive e protettive e dei sistemi di controllo; procedure di sicurezza; programmi di informazione e formazione; partecipazione alle consultazioni e alla riunione periodica; informazioni ai lavoratori.",["Ho elencato i compiti dell’art. 33","Ho incluso formazione e riunione periodica"]),
  ("Definisci le priorità dell’anno motivandole.",8,"Aggiornamento del DVR per le due nuove linee; analisi degli infortuni e dei quasi incidenti per individuare cause ricorrenti; valutazione specifica della movimentazione dei carichi e del rumore sulle nuove linee; revisione delle procedure di accesso alle celle frigorifere; piano formativo per i neoassunti delle nuove linee.",["Ho collegato le priorità ai dati","Ho dato priorità ai cambiamenti","Ho incluso l’analisi degli eventi"],None,150),
  ("Proponi indicatori per misurare il lavoro del servizio.",6,"Percentuale di azioni del programma chiuse nei tempi; numero di sopralluoghi svolti; quasi incidenti segnalati e analizzati; indici di frequenza e gravità; formazione erogata rispetto a quella pianificata.",["Ho proposto indicatori proattivi","Ho proposto indicatori reattivi"]),
  ("Come rendiconti il programma al datore di lavoro?",6,"Con un report periodico, ad esempio trimestrale, e una sintesi annuale per la riunione periodica: stato delle azioni, criticità, proposte con costi e scadenze, segnalazioni scritte per i rischi non ancora affrontati.",["Ho previsto report periodici","Ho previsto segnalazioni scritte"])],
 "Nel laboratorio prepari il programma annuale del servizio di prevenzione e protezione di un’impresa alimentare: compiti da coprire, priorità, indicatori e rendicontazione al datore di lavoro. Confronta ogni risposta con la soluzione di riferimento.","Artt. 31-35 D.lgs. 81/2008")])
EA(K,'ZR07','Medico competente e RLS',[SC("Il medico che non fa il sopralluogo","Il medico competente di un’impresa metalmeccanica effettua le visite in un ambulatorio esterno e non visita gli ambienti di lavoro da tre anni. Nel DVR non è indicata una periodicità diversa.",[
 ("Che cosa prevede la norma?",[["Il medico competente visita gli ambienti di lavoro almeno una volta l’anno o con la diversa cadenza stabilita nel DVR",True,"Corretto: art. 25, comma 1, lettera l)."],["Non deve mai visitarli",False,"La visita degli ambienti è un obbligo."],["Solo dopo un infortunio",False,"Ha una cadenza periodica."]]),
 ("Come interviene l’RSPP?",[["Segnala per iscritto la situazione al datore di lavoro e propone di programmare il sopralluogo con il medico",True,"Corretto: l’RSPP coordina e segnala."],["Fa lui il sopralluogo al posto del medico",False,"Non sostituisce il medico."],["Non è un suo problema",False,"Il funzionamento del sistema lo riguarda."]]),
 ("Perché il sopralluogo è importante anche per l’RLS?",[["Perché alimenta la valutazione dei rischi e la relazione sanitaria che l’RLS esamina nella riunione periodica",True,"Corretto."],["Non lo riguarda",False,"L’RLS partecipa alla riunione periodica."],["Perché l’RLS deve firmare il verbale del medico",False,"Non è previsto."]])],
 "Il medico competente conosce i luoghi di lavoro solo visitandoli: il sopralluogo annuale, o con la cadenza del DVR, alimenta valutazione dei rischi e sorveglianza sanitaria.","Un medico competente che non visita gli ambienti. Intervieni.","Art. 25 D.lgs. 81/2008")])
EA(K,'ZR08','Gli altri soggetti',[SC("Il lavoratore autonomo in officina","Un elettricista lavoratore autonomo viene chiamato per un intervento sul quadro di un reparto in funzione.",[
 ("Quali obblighi ha l’elettricista come autonomo?",[["Usare attrezzature conformi e DPI adeguati e munirsi di tessera di riconoscimento negli appalti",True,"Corretto: art. 21."],["Nessuno, non è un dipendente",False,"L’art. 21 prevede obblighi specifici."],["Gli stessi di un datore di lavoro con dipendenti",False,"Gli obblighi sono specifici."]]),
 ("Che cosa deve fare il committente?",[["Verificarne l’idoneità tecnico-professionale e informarlo sui rischi dell’ambiente e sulle emergenze",True,"Corretto: art. 26."],["Nulla",False,"Ha obblighi di verifica e informazione."],["Fargli firmare uno scarico di responsabilità",False,"Non ha valore."]]),
 ("L’intervento richiede di lavorare vicino a parti in tensione. Che cosa serve?",[["Che sia persona esperta o avvertita secondo le norme tecniche e che il lavoro sia organizzato con le procedure previste",True,"Corretto: CEI 11-27."],["Basta che sia rapido",False,"La velocità non riduce il rischio."],["Basta un guanto qualunque",False,"Servono procedure e DPI adeguati."]])],
 "Anche il lavoratore autonomo ha obblighi propri; il committente verifica, informa e coordina, e i lavori elettrici richiedono qualificazione e procedure.","Un elettricista autonomo in un reparto attivo. Organizza l’intervento.","Artt. 21, 26 e 82 D.lgs. 81/2008 · CEI 11-27")])
EA(K,'ZR09','Dimostrare la vigilanza: che cosa conta in giudizio',[LB("Laboratorio · Il fascicolo della vigilanza","Organizzi le evidenze della vigilanza dei preposti in uno stabilimento di stampaggio.",[
  ["Preposti","6 capiturno su tre turni"],["Situazione","nessuna registrazione; i richiami avvengono a voce"],["Rischio principale","esclusione dei dispositivi di sicurezza delle presse per velocizzare il cambio stampo"]],[
  ("Quali evidenze dimostrano una vigilanza effettiva?",6,"Registrazioni dei giri di sicurezza con data, area e comportamenti osservati; richiami e segnalazioni scritte; verbali delle brevi riunioni di inizio turno; annotazione delle interruzioni dell’attività; esiti delle verifiche sui dispositivi delle presse.",["Ho elencato evidenze documentabili","Ho incluso interruzioni e richiami"]),
  ("Progetta una scheda di giro di sicurezza per il cambio stampo.",8,"Data, turno, preposto; pressa e operatori; controllo dell’uso della procedura di cambio stampo; stato dei ripari e degli interblocchi; uso dei DPI; comportamenti corretti riconosciuti; non conformità e intervento svolto; firma.",["Ho previsto i campi essenziali","Ho incluso i dispositivi delle presse","Ho incluso intervento e riconoscimento"],None,120),
  ("Con quale frequenza e intensità imposti la vigilanza?",6,"Adeguata al rischio e all’esperienza: più frequente durante i cambi stampo e con operatori nuovi; non controllo continuo di ogni gesto, ma presenza nei momenti critici e verifiche a campione.",["Ho collegato la frequenza al rischio","Ho evitato il controllo continuo"]),
  ("Chi vigila sui preposti e con quali strumenti?",6,"Il dirigente o il datore di lavoro, con l’esame periodico delle schede, sopralluoghi a campione, indicatori come numero di giri svolti e azioni chiuse, e colloqui con i preposti: le prassi tollerate provano la carenza di vigilanza a tutti i livelli.",["Ho indicato chi vigila sui preposti","Ho proposto strumenti e indicatori"])],
 "Nel laboratorio organizzi le evidenze della vigilanza dei preposti in uno stabilimento di stampaggio: evidenze utili, scheda di giro di sicurezza, frequenza adeguata al rischio e vigilanza sui preposti. Confronta ogni risposta con la soluzione di riferimento.","Art. 19 D.lgs. 81/2008 · Cass. pen., Sez. IV, n. 32520/2025")])
EA(K,'ZR10','Giurisprudenza: posizioni di garanzia e RSPP',[LB("Laboratorio · Ripartire le responsabilità","Analizzi un infortunio avvenuto durante un appalto di manutenzione in uno stabilimento chimico, applicando i principi consolidati della giurisprudenza.",[
  ["Evento","un manutentore dell’impresa appaltatrice cade da una passerella priva di parapetto in un’area del committente"],["Committente","aveva scelto l’appaltatore per il prezzo più basso, senza verificare formazione e attrezzature"],["Appaltatore","nessun preposto presente in cantiere"],["RSPP del committente","aveva segnalato per iscritto la mancanza del parapetto un anno prima"],["Lavoratore","era salito sulla passerella per un compito previsto dall’ordine di lavoro"]],[
  ("Il comportamento del lavoratore può escludere la responsabilità dei garanti?",6,"No: ha svolto un compito previsto, senza attivare un rischio eccentrico rispetto all’attività affidata. Solo un comportamento abnorme, esorbitante dal procedimento di lavoro e dalle direttive, escluderebbe la responsabilità.",["Ho applicato il criterio dell’area di rischio","Ho escluso l’abnormità"]),
  ("Qual è la posizione del committente?",6,"Risponde per i rischi del proprio ambiente non eliminati, come il parapetto mancante, e per la scelta dell’appaltatore senza verificarne l’idoneità: culpa in eligendo e omessa cooperazione e coordinamento.",["Ho indicato il rischio dell’ambiente","Ho indicato la culpa in eligendo"]),
  ("Qual è la posizione dell’appaltatore e dell’RSPP?",7,"L’appaltatore risponde per la mancata vigilanza tramite un preposto e per la mancata valutazione dei rischi del lavoro. L’RSPP del committente ha segnalato per iscritto il rischio: la segnalazione documentata lo tutela, perché l’omissione è imputabile a chi aveva i poteri di intervento.",["Ho indicato la vigilanza mancante dell’appaltatore","Ho valutato la segnalazione dell’RSPP"]),
  ("Quali azioni avrebbero evitato l’evento?",7,"Installazione del parapetto dopo la segnalazione; verifica dell’idoneità tecnico-professionale dell’appaltatore; DUVRI con le aree a rischio di caduta; preposto dell’appaltatore presente; permesso di lavoro per le aree in quota.",["Ho indicato la misura tecnica","Ho indicato verifica e DUVRI","Ho indicato preposto e permessi"])],
 "Nel laboratorio applichi i principi consolidati della giurisprudenza a una caduta durante un appalto: comportamento del lavoratore, posizione del committente, dell’appaltatore e dell’RSPP, azioni preventive. Confronta ogni risposta con la soluzione di riferimento.","Artt. 18, 26 e 33 D.lgs. 81/2008 · Cass. pen., Sez. IV, n. 10460/2025")])
EA(K,'ZR11','Esercitazione 1 · Qualificazione del comportamento abnorme',[SC("Il gesto imprevedibile?","Un operaio, a fine turno, sale sul nastro trasportatore fermo ma non sezionato per recuperare il proprio telefono caduto. Un collega riavvia il nastro e l’operaio si ferisce.",[
 ("Il comportamento è abnorme?",[["Potrebbe esserlo se è del tutto estraneo alle mansioni e imprevedibile; va però verificato se l’accesso al nastro era una prassi tollerata",True,"Corretto: l’abnormità si valuta rispetto all’area di rischio governata dal garante e alle prassi conosciute."],["Sì, sempre: il telefono non è lavoro",False,"Conta anche se la situazione era prevedibile e tollerata."],["No, mai",False,"L’abnormità esiste, ma è un’eccezione."]]),
 ("Quale elemento rende il riavvio comunque rilevante per i garanti?",[["L’assenza di una procedura di sezionamento e blocco prima di accedere al nastro",True,"Corretto: il riavvio non controllato è un rischio dell’attività che il garante doveva governare."],["Il colore del nastro",False,"Non è rilevante."],["L’ora del turno",False,"Non decide la responsabilità."]]),
 ("Quali misure eviterebbero il ripetersi?",[["Ripari che impediscano l’accesso, procedura di sezionamento con lucchetti personali e segnalazione dei riavvii",True,"Corretto."],["Divieto di portare telefoni",False,"Non elimina il rischio di accesso."],["Un cartello generico",False,"Non basta."]])],
 "L’abnormità esclude la responsabilità solo per condotte esorbitanti e imprevedibili; prassi tollerate e assenza di procedure di blocco riportano il rischio nell’area governata dal garante.","Un accesso improprio a un nastro. Qualifica il comportamento.","Cass. pen., Sez. IV, n. 10460/2025 · art. 71 D.lgs. 81/2008")])
EA(K,'ZR12','Aggiornamento e decadenza del credito formativo',[SC("Il credito decaduto","Un datore di lavoro ha concluso il modulo per svolgere i compiti del servizio di prevenzione nel 2013 e da allora non ha mai fatto aggiornamenti né ha svolto la funzione.",[
 ("Può riprendere la funzione con il solo aggiornamento?",[["No: dopo dieci anni senza aggiornamento né esercizio della funzione il credito decade e il percorso va ripetuto",True,"Corretto: FAQ n. 8."],["Sì, con 8 ore",False,"Il credito è decaduto."],["Sì, senza alcuna formazione",False,"Non è ammesso."]]),
 ("Quale prerequisito serve per il modulo comune?",[["Il corso per datori di lavoro di 16 ore",True,"Corretto: FAQ n. 30."],["Nessuno",False,"È previsto un prerequisito."],["Il diploma tecnico",False,"Non è il prerequisito."]]),
 ("Come sarà l’aggiornamento successivo?",[["Almeno 8 ore ogni cinque anni, erogabile in e-learning, con verifica finale di almeno 10 domande",True,"Corretto."],["40 ore ogni anno",False,"Non è la regola per il DLSPP."],["Senza verifica",False,"La verifica è obbligatoria."]])],
 "Il credito formativo non è eterno: dopo dieci anni di inattività va ripreso il percorso, e l’aggiornamento quinquennale richiede sempre una verifica finale.","Un datore di lavoro vuole riprendere i compiti del servizio. Verifica la sua formazione.","Accordo 17 aprile 2025 · FAQ 27 marzo 2026")])
